create function retirer_stock() returns trigger
language plpgsql
as $$
begin
  update produits set stock = stock - new.quantite where id = new.produit_id;
  return new;
end;
$$;

create trigger apres_commande
after insert on commandes
for each row execute function retirer_stock();

insert into commandes (client_id, produit_id, quantite) values ('22222222-2222-2222-2222-222222222222', 4, 3);
select nom, stock from produits where id = 4;

create function verifier_stock() returns trigger
language plpgsql
as $$
begin
  if (select stock from produits where id = new.produit_id) < new.quantite then
    raise exception 'stock insuffisant';
  end if;
  return new;
end;
$$;

create trigger avant_commande
before insert on commandes
for each row execute function verifier_stock();

insert into commandes (client_id, produit_id, quantite) values ('11111111-1111-1111-1111-111111111111', 2, 5);
select count(*)::int as commandes from commandes;

