create table historique (
  commande_id bigint not null,
  ancien text not null,
  nouveau text not null
);

create function noter_statut() returns trigger
language plpgsql
as $$
begin
  if new.statut <> old.statut then
    insert into historique values (new.id, old.statut, new.statut);
  end if;
  return new;
end;
$$;

create trigger apres_statut
after update on commandes
for each row execute function noter_statut();
